42	
43	/**
44	 * Holds a {@link JavaRDD} of objects.
45	 *
46	 * @param <T> type of object.
47	 */
48	public class HoodieJavaRDD<T> implements HoodieData<T> {
49	
50	  private final JavaRDD<T> rddData;
51	
52	  private HoodieJavaRDD(JavaRDD<T> rddData) {
53	    this.rddData = rddData;
54	  }
55	
56	  /**
57	   * @param rddData a {@link JavaRDD} of objects in type T.
58	   * @param <T>     type of object.
59	   * @return a new instance containing the {@link JavaRDD<T>} reference.
60	   */
61	  public static <T> HoodieJavaRDD<T> of(JavaRDD<T> rddData) {
62	    return new HoodieJavaRDD<>(rddData);
63	  }
64	
65	  /**
66	   * @param data        a {@link List} of objects in type T.
67	   * @param context     {@link HoodieSparkEngineContext} to use.
68	   * @param parallelism parallelism for the {@link JavaRDD<T>}.
69	   * @param <T>         type of object.
70	   * @return a new instance containing the {@link JavaRDD<T>} instance.
71	   */
72	  public static <T> HoodieJavaRDD<T> of(
73	      List<T> data, HoodieSparkEngineContext context, int parallelism) {
74	    return new HoodieJavaRDD<>(context.getJavaSparkContext().parallelize(data, parallelism));
75	  }
76	
77	  /**
78	   * @param hoodieData {@link HoodieJavaRDD <T>} instance containing the {@link JavaRDD} of objects.
79	   * @param <T>        type of object.
80	   * @return the a {@link JavaRDD} of objects in type T.
81	   */
82	  public static <T> JavaRDD<T> getJavaRDD(HoodieData<T> hoodieData) {
83	    return ((HoodieJavaRDD<T>) hoodieData).rddData;
84	  }
85	
86	  public static <K, V> JavaPairRDD<K, V> getJavaRDD(HoodiePairData<K, V> hoodieData) {
87	    return ((HoodieJavaPairRDD<K, V>) hoodieData).get();
88	  }
89	
90	  @Override
91	  public int getId() {
92	    return rddData.id();
93	  }
94	
95	  @Override
96	  public void persist(String level) {
97	    rddData.persist(StorageLevel.fromString(level));
98	  }
99	
100	  @Override
101	  public void persist(String level, HoodieEngineContext engineContext, HoodieDataCacheKey cacheKey) {
102	    engineContext.putCachedDataIds(cacheKey, this.getId());
103	    rddData.persist(StorageLevel.fromString(level));
104	  }
105	
106	  @Override
107	  public void unpersist() {
108	    rddData.unpersist();
109	  }
110	
111	  @Override
112	  public boolean isEmpty() {
113	    return rddData.isEmpty();
114	  }
115	
116	  @Override
117	  public long count() {
118	    return rddData.count();
119	  }
120	
121	  @Override
122	  public int getNumPartitions() {
123	    return rddData.getNumPartitions();
124	  }
125	
126	  @Override
127	  public int deduceNumPartitions() {
128	    // for source rdd, the partitioner is None
129	    final Optional<Partitioner> partitioner = rddData.partitioner();
130	    if (partitioner.isPresent()) {
131	      int partPartitions = partitioner.get().numPartitions();
132	      if (partPartitions > 0) {
133	        return partPartitions;
134	      }
135	    }
136	
137	    if (SQLConf.get().contains(SQLConf.SHUFFLE_PARTITIONS().key())) {
138	      return Integer.parseInt(SQLConf.get().getConfString(SQLConf.SHUFFLE_PARTITIONS().key()));
139	    } else if (rddData.context().conf().contains("spark.default.parallelism")) {
140	      return rddData.context().defaultParallelism();
141	    } else {
142	      return rddData.getNumPartitions();
143	    }
144	  }
145	
146	  @Override
147	  public <O> HoodieData<O> map(SerializableFunction<T, O> func) {
148	    return HoodieJavaRDD.of(rddData.map(func::apply));
149	  }
150	
151	  @Override
152	  public <O> HoodieData<O> mapPartitions(SerializableFunction<Iterator<T>, Iterator<O>> func, boolean preservesPartitioning) {
153	    return HoodieJavaRDD.of(rddData.mapPartitions(iter -> CloseableIteratorListener.addListener(func.apply(iter)), preservesPartitioning));
154	  }
155	
156	  @Override
157	  public <O> HoodieData<O> flatMap(SerializableFunction<T, Iterator<O>> func) {
158	    // NOTE: Unrolling this lambda into a method reference results in [[ClassCastException]]
159	    //       due to weird interop b/w Scala and Java
160	    return HoodieJavaRDD.of(rddData.flatMap(e -> CloseableIteratorListener.addListener(func.apply(e))));
161	  }
162	
163	  @Override
164	  public <K, V> HoodiePairData<K, V> flatMapToPair(SerializableFunction<T, Iterator<? extends Pair<K, V>>> func) {
165	    return HoodieJavaPairRDD.of(
166	        rddData.flatMapToPair(e ->
167	            new MappingIterator<>(CloseableIteratorListener.addListener(func.apply(e)), p -> new Tuple2<>(p.getKey(), p.getValue()))));
168	  }
169	
170	  @Override
171	  public <K, V> HoodiePairData<K, V> mapToPair(SerializablePairFunction<T, K, V> func) {
172	    return HoodieJavaPairRDD.of(rddData.mapToPair(input -> {
173	      Pair<K, V> pair = func.call(input);
174	      return new Tuple2<>(pair.getLeft(), pair.getRight());
175	    }));
176	  }
177	
178	  @Override
179	  public HoodieData<T> distinct() {
180	    return HoodieJavaRDD.of(rddData.distinct());
181	  }
182	
183	  @Override
184	  public HoodieData<T> distinct(int parallelism) {
185	    return HoodieJavaRDD.of(rddData.distinct(parallelism));
186	  }
187	
188	  @Override
189	  public HoodieData<T> filter(SerializableFunction<T, Boolean> filterFunc) {
190	    return HoodieJavaRDD.of(rddData.filter(filterFunc::apply));
191	  }
192	
193	  @Override
194	  public HoodieData<T> union(HoodieData<T> other) {
195	    return HoodieJavaRDD.of(rddData.union(((HoodieJavaRDD<T>) other).rddData));
196	  }
197	
198	  @Override
199	  public List<T> collectAsList() {
200	    return rddData.collect();
201	  }
202	
203	  @Override
204	  public HoodieData<T> repartition(int parallelism) {
205	    return HoodieJavaRDD.of(rddData.repartition(parallelism));
206	  }
207	}
