39	/**
40	 * In-memory implementation of {@link HoodieData} holding internally a {@link Stream} of objects.
41	 *
42	 * {@link HoodieListData} can have either of the 2 execution semantics:
43	 *
44	 * <ol>
45	 *   <li>Eager: with every operation being executed right away</li>
46	 *   <li>Lazy: with every operation being "stacked up", with it execution postponed until
47	 *   "terminal" operation is invoked</li>
48	 * </ol>
49	 *
50	 * NOTE: This is an in-memory counterpart for {@code HoodieJavaRDD}, and it strives to provide
51	 *       similar semantic as RDD container -- all intermediate (non-terminal, not de-referencing
52	 *       the stream like "collect", "groupBy", etc) operations are executed *lazily*.
53	 *       This allows to make sure that compute/memory churn is minimal since only necessary
54	 *       computations will ultimately be performed.
55	 *
56	 *       Please note, however, that while RDD container allows the same collection to be
57	 *       de-referenced more than once (ie terminal operation invoked more than once),
58	 *       {@link HoodieListData} allows that only when instantiated w/ an eager execution semantic.
59	 *
60	 * @param <T> type of object.
61	 */
62	public class HoodieListData<T> extends HoodieBaseListData<T> implements HoodieData<T> {
63	
64	  private HoodieListData(List<T> data, boolean lazy) {
65	    super(data, lazy);
66	  }
67	
68	  HoodieListData(Stream<T> dataStream, boolean lazy) {
69	    super(dataStream, lazy);
70	  }
71	
72	  /**
73	   * Creates instance of {@link HoodieListData} bearing *eager* execution semantic
74	   *
75	   * @param listData a {@link List} of objects in type T
76	   * @param <T>      type of object
77	   * @return a new instance containing the {@link List<T>} reference
78	   */
79	  public static <T> HoodieListData<T> eager(List<T> listData) {
80	    return new HoodieListData<>(listData, false);
81	  }
82	
83	  /**
84	   * Creates instance of {@link HoodieListData} bearing *lazy* execution semantic
85	   *
86	   * @param listData a {@link List} of objects in type T
87	   * @param <T>      type of object
88	   * @return a new instance containing the {@link List<T>} reference
89	   */
90	  public static <T> HoodieListData<T> lazy(List<T> listData) {
91	    return new HoodieListData<>(listData, true);
92	  }
93	
94	  @Override
95	  public int getId() {
96	    return -1;
97	  }
98	
99	  @Override
100	  public void persist(String level) {
101	    // No OP
102	  }
103	
104	  @Override
105	  public void persist(String level, HoodieEngineContext engineContext, HoodieDataCacheKey cacheKey) {
106	    // No OP
107	  }
108	
109	  @Override
110	  public void unpersist() {
111	    // No OP
112	  }
113	
114	  @Override
115	  public <O> HoodieData<O> map(SerializableFunction<T, O> func) {
116	    return new HoodieListData<>(asStream().map(throwingMapWrapper(func)), lazy);
117	  }
118	
119	  @Override
120	  public <O> HoodieData<O> mapPartitions(SerializableFunction<Iterator<T>, Iterator<O>> func, boolean preservesPartitioning) {
121	    Function<Iterator<T>, Iterator<O>> mapper = throwingMapWrapper(func);
122	    Iterator<T> iterator = asStream().iterator();
123	    Iterator<O> newIterator = mapper.apply(iterator);
124	    return new HoodieListData<>(
125	        StreamSupport.stream(
126	            Spliterators.spliteratorUnknownSize(
127	                newIterator, Spliterator.ORDERED), true).onClose(new IteratorCloser(newIterator)),
128	        lazy
129	    );
130	  }
131	
132	  @Override
133	  public <O> HoodieData<O> flatMap(SerializableFunction<T, Iterator<O>> func) {
134	    Function<T, Iterator<O>> mapper = throwingMapWrapper(func);
135	    Stream<O> mappedStream = asStream().flatMap(e -> {
136	      Iterator<O> iterator = mapper.apply(e);
137	      return StreamSupport.stream(
138	          Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), true).onClose(new IteratorCloser(iterator));
139	    });
140	    return new HoodieListData<>(mappedStream, lazy);
141	  }
142	
143	  @Override
144	  public <K, V> HoodiePairData<K, V> flatMapToPair(SerializableFunction<T, Iterator<? extends Pair<K, V>>> func) {
145	    Function<T, Iterator<? extends Pair<K, V>>> mapper = throwingMapWrapper(func);
146	    Stream<Pair<K, V>> mappedStream = asStream().flatMap(e -> {
147	      Iterator<? extends Pair<K, V>> iterator = mapper.apply(e);
148	      return StreamSupport.stream(
149	          Spliterators.spliteratorUnknownSize(iterator, Spliterator.ORDERED), true).onClose(new IteratorCloser(iterator));
150	    });
151	
152	    return new HoodieListPairData<>(mappedStream, lazy);
153	  }
154	
155	  @Override
156	  public <K, V> HoodiePairData<K, V> mapToPair(SerializablePairFunction<T, K, V> func) {
157	    Function<T, Pair<K, V>> throwableMapToPairFunc = throwingMapToPairWrapper(func);
158	    return new HoodieListPairData<>(asStream().map(throwableMapToPairFunc), lazy);
159	  }
160	
161	  @Override
162	  public HoodieData<T> distinct() {
163	    return new HoodieListData<>(asStream().distinct(), lazy);
164	  }
165	
166	  @Override
167	  public HoodieData<T> distinct(int parallelism) {
168	    return distinct();
169	  }
170	
171	  @Override
172	  public <O> HoodieData<T> distinctWithKey(SerializableFunction<T, O> keyGetter, int parallelism) {
173	    return mapToPair(i -> Pair.of(keyGetter.apply(i), i))
174	        .reduceByKey((value1, value2) -> value1, parallelism)
175	        .values();
176	  }
177	
178	  @Override
179	  public HoodieData<T> filter(SerializableFunction<T, Boolean> filterFunc) {
180	    return new HoodieListData<>(asStream().filter(r -> throwingMapWrapper(filterFunc).apply(r)), lazy);
181	  }
182	
183	  @Override
184	  public HoodieData<T> union(HoodieData<T> other) {
185	    ValidationUtils.checkArgument(other instanceof HoodieListData);
186	    return new HoodieListData<>(Stream.concat(asStream(), ((HoodieListData<T>)other).asStream()), lazy);
187	  }
188	
189	  @Override
190	  public HoodieData<T> repartition(int parallelism) {
191	    // no op
192	    return this;
193	  }
194	
195	  @Override
196	  public boolean isEmpty() {
197	    return super.isEmpty();
198	  }
199	
200	  @Override
201	  public long count() {
202	    return super.count();
203	  }
204	
205	  @Override
206	  public int getNumPartitions() {
207	    return 1;
208	  }
