import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Tracks intermediate, uncached distributed data collections (i.e. {@link HoodieData} and
 * {@link HoodiePairData}) produced while reading from the metadata table and ensures that their
 * resources are released if the enclosing operation fails.
 *
 * <p>Some read paths in the metadata table build up chains of distributed collections that are
 * never explicitly cached/unpersisted. When an operation fails part-way through, the persisted
 * intermediate collections (and their upstream dependencies) would otherwise be leaked, holding on
 * to executor memory until the {@code SparkContext} is torn down. This manager tracks such
 * collections per-thread and, on exception, recursively un-persists them via
 * {@link HoodieData#unpersistWithDependencies()} / {@link HoodiePairData#unpersistWithDependencies()}.
 *
 * <p>Tracking is isolated per-thread (keyed by the thread id), so cleanup triggered on one thread
 * does not affect collections tracked by another thread.
 */
public class HoodieDataCleanupManager {

  private static final Logger LOG = LoggerFactory.getLogger(HoodieDataCleanupManager.class);

  private final ConcurrentHashMap<Long, List<Object>> threadPersistedData = new ConcurrentHashMap<>();

  public HoodieDataCleanupManager() {
  }

  /**
   * Tracks a {@link HoodiePairData} collection for the current thread so that it can be released if
   * the enclosing operation fails.
   */
  public void trackPersistedData(HoodiePairData<?, ?> data) {
    trackPersistedDataInternal(data);
  }

  /**
   * Tracks a {@link HoodieData} collection for the current thread so that it can be released if the
   * enclosing operation fails.
   */
  public void trackPersistedData(HoodieData<?> data) {
    trackPersistedDataInternal(data);
  }

  private void trackPersistedDataInternal(Object data) {
    if (data == null) {
      return;
    }
    threadPersistedData
        .computeIfAbsent(Thread.currentThread().getId(), k -> new ArrayList<>())
        .add(data);
  }

  /**
   * Executes the provided {@code operation}, returning its result on success. If the operation
   * throws, all data collections tracked for the current thread are recursively un-persisted, the
   * tracking list for the current thread is cleared, and the original exception is re-thrown.
   *
   * @param operation the operation to execute
   * @param <T>       the operation's result type
   * @return the result of the operation
   */
  public <T> T ensureDataCleanupOnException(SerializableFunctionUnchecked<Void, T> operation) {
    try {
      return operation.apply(null);
    } catch (Throwable t) {
      cleanupPersistedDataForCurrentThread();
      throw t;
    }
  }

  private void cleanupPersistedDataForCurrentThread() {
    long threadId = Thread.currentThread().getId();
    List<Object> persistedData = threadPersistedData.remove(threadId);
    if (persistedData == null) {
      return;
    }
    for (Object data : persistedData) {
      try {
        if (data instanceof HoodieData) {
          ((HoodieData<?>) data).unpersistWithDependencies();
        } else if (data instanceof HoodiePairData) {
          ((HoodiePairData<?, ?>) data).unpersistWithDependencies();
        }
        // Silently skip nulls and any objects that are neither HoodieData nor HoodiePairData
      } catch (Exception e) {
        // Continue releasing the remaining tracked collections even if one fails
        LOG.warn("Failed to unpersist tracked data during exception cleanup", e);
      }
    }
  }

  /**
   * Package-private accessor exposing the per-thread tracking map for testing.
   */
  ConcurrentHashMap<Long, List<Object>> getThreadPersistedData() {
    return threadPersistedData;
  }
}
